import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const w=JSON.parse('{"title":"Kimi chat and Agent","description":"Audience: frontend engineers picking a Moonshot surface. You need a browser or the Kimi app, not a repo checkout.","frontmatter":{"title":"Kimi chat and Agent","description":"Audience: frontend engineers picking a Moonshot surface. You need a browser or the Kimi app, not a repo checkout.","domain":"product","tags":["chat"],"role":"tutorial"},"headers":[],"relativePath":"products/kimi/kimi.md","filePath":"products/kimi/kimi.md","lastUpdated":1787110548000}'),i={name:"products/kimi/kimi.md"};function s(n,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kimi-chat-and-agent" tabindex="-1">Kimi chat and Agent <a class="header-anchor" href="#kimi-chat-and-agent" aria-label="Permalink to &quot;Kimi chat and Agent&quot;">​</a></h1><blockquote><p><strong>Kimi</strong> is Moonshot AI&#39;s all-in-one workspace. Official product copy (<a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a>): built-in Agent capabilities for deep research, slides, sheets, documents, and websites.</p><p><strong>Kimi Agent</strong> official definition (<a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a>): &quot;Kimi Agent is an autonomous AI assistant that handles complex tasks end-to-end. Powered by Kimi K3, it uses 20+ tools to build websites, generate documents, analyze data, and more.&quot;</p><p>This page maps kimi.com, the products page, and the help center. It is <strong>not</strong> Kimi Code — that is <a href="/products/kimi-code/">Kimi Code</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers choosing a Kimi surface. Browser or Kimi app. No checkout.</p><p><strong>Goals:</strong> open kimi.com, tell Chat / Agent / Swarm / Claw apart, finish one Agent task, know which official table holds credits.</p><p><strong>Non-goals:</strong> Kimi Code install; invented CNY prices; treating Moderato as Go; model internals. Mechanisms: <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>One workspace, several official clients:</p><table tabindex="0"><thead><tr><th>Client</th><th>Official entry</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td>Agent</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td>Agent Swarm</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td>Kimi Claw</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td>App</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a> footer &quot;Scan to download Kimi App&quot;</td></tr></tbody></table><p>Home sidebar labels copied from <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a>: <strong>Plugins, Scheduled Tasks, Slides, Swarm, Deep Research, Docs, Websites, Sheets, Design</strong>, plus <strong>Kimi Work / Kimi Code / Kimi Claw</strong>. New chat shortcut on the homepage: <strong>⌘K</strong>.</p><p>Agent capabilities (<a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a>):</p><table tabindex="0"><thead><tr><th>Capability</th><th>Official description</th></tr></thead><tbody><tr><td>Websites</td><td>Generate and deploy responsive web apps</td></tr><tr><td>Docs</td><td>Word, PDF, Markdown</td></tr><tr><td>Sheets</td><td>Excel / CSV; official text: up to 1,000-row Excel</td></tr><tr><td>Slides</td><td>Automated PPT</td></tr><tr><td>Deep Research</td><td>10,000+ word reports</td></tr><tr><td>Agent Swarm</td><td>Up to 300 sub-agents; 4,000+ tool calls</td></tr><tr><td>Kimi Claw</td><td>Cloud automation; help center cites 5,000+ ClawHub skills</td></tr></tbody></table><p>How it works (same page): task planning → tool invocation (20+ tools) → autonomous execution → error handling → deliverables.</p><h2 id="first-session-chat" tabindex="-1">First session: chat <a class="header-anchor" href="#first-session-chat" aria-label="Permalink to &quot;First session: chat&quot;">​</a></h2><ol><li>Open <a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a> and sign in. Signed-out sidebar: &quot;Log in to sync chat history&quot;.</li><li>Type in the box. Homepage: &quot;Ask anything, or task an agent...&quot;</li><li>Chat credits: official membership page — &quot;In Chat, K2.6 is free for all users and does not consume credits&quot; (<a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">membership overview</a>).</li></ol><p>For durable context, create a <strong>Project</strong> instead of re-uploading the same files. Next section.</p><h2 id="first-agent-task" tabindex="-1">First Agent task <a class="header-anchor" href="#first-agent-task" aria-label="Permalink to &quot;First Agent task&quot;">​</a></h2><p>Official entries (<a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a>):</p><ul><li><strong>Web:</strong> <a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">https://www.kimi.com/agent</a></li><li><strong>Mobile / tablet:</strong> Kimi app → model switch → <strong>K3</strong> or <strong>K3 Swarm</strong></li></ul><p>Official steps:</p><ol><li>Describe the task clearly. Official examples include creating voting-site code and analyzing a market.</li><li>Watch planning, tools, visited URLs, intermediate code.</li><li>Download or share: code project, folder, analysis, Word / PDF / PPT.</li></ol><p>Official use cases: website development, multimedia content, document comparison / translation, data analysis, slides, format conversion.</p><h2 id="agent-swarm" tabindex="-1">Agent Swarm <a class="header-anchor" href="#agent-swarm" aria-label="Permalink to &quot;Agent Swarm&quot;">​</a></h2><p>Official definition (<a href="https://www.kimi.com/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a> / <a href="https://www.kimi.com/zh-hans/help/agent/agent-swarm" target="_blank" rel="noreferrer">zh-hans</a>): scale-out architecture, up to <strong>300</strong> sub-agents, no preset roles or hand-built workflows. Official claims: about <strong>4.5×</strong> faster than a single Agent; more than <strong>4,000</strong> tool calls per task. Currently powered by <strong>Kimi K3 (K3 Swarm)</strong>.</p><p><strong>Entries:</strong></p><ul><li>Web: <a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">https://www.kimi.com/agent-swarm</a></li><li>Mobile: Kimi app model switch → <strong>K3 Swarm</strong></li></ul><p><strong>Access:</strong> <strong>Moderato, Allegretto, Allegro, and Vivace</strong>. Official: these tasks consume noticeably more credits than standard Agent. <strong>[Beta]</strong> means early, limited rollout.</p><p>Official steps: describe the task → watch sub-agents → take deliverables → later turns auto-route between chat and Agent.</p><p>Good for: large retrieval, batch download, 100+ documents, long writing, complex coding, Office automation. Bad for one-shot chit-chat.</p><h2 id="kimi-claw" tabindex="-1">Kimi Claw <a class="header-anchor" href="#kimi-claw" aria-label="Permalink to &quot;Kimi Claw&quot;">​</a></h2><p>Official positioning (<a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a>): talk to <strong>OpenClaw</strong> inside Kimi. OpenClaw is &quot;an AI assistant with a distinct personality and long-term memory.&quot;</p><p><strong>One-click cloud deploy:</strong></p><ol><li>Sign in at <a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></li><li>Click <strong>Create</strong> Kimi Claw</li><li>Wait for automatic setup (official: usually a few minutes)</li><li>Set a nickname; <strong>Settings → Chat channels</strong> for WeChat / Feishu / WeCom and others</li></ol><p>Official limits: one-click deploy is <strong>Allegretto and higher</strong>. Default model <strong>Kimi K2.6</strong>, billed against <strong>membership credits</strong>, with Kimi Web Search configured. Can deploy to Feishu, WeCom, Weibo, and other platforms.</p><p><strong>Link an existing OpenClaw:</strong> <strong>Link existing OpenClaw</strong>, then install the Kimi plugin on the machine that already runs OpenClaw.</p><p><strong>Claw group chat</strong> (<a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a>): sidebar <strong>+</strong> → <strong>Start Group Chat</strong>, required Group Name and Group Goal, pick linked Claws. Kimi assigns a <strong>Conductor</strong>. Send <code>/stop</code> in the main chat to force-interrupt. Set group rules in plain language. Allegretto+; membership table lists 10 group chats.</p><p>Switching Claw&#39;s default model to K3 is documented on the Claw overview as edits to <code>/root/.openclaw/openclaw.json</code> (or your real install path). That is <strong>OpenClaw config</strong>, not a kimi.com chat command. Copy the official snippet, and back up first.</p><h2 id="projects-memory-skills-plugins-scheduled-tasks" tabindex="-1">Projects, memory, Skills, plugins, scheduled tasks <a class="header-anchor" href="#projects-memory-skills-plugins-scheduled-tasks" aria-label="Permalink to &quot;Projects, memory, Skills, plugins, scheduled tasks&quot;">​</a></h2><p>Cross-cutting Features: <a href="https://www.kimi.com/help/features" target="_blank" rel="noreferrer">help/features</a>.</p><h3 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>: keep files, chats, and instructions together. Sidebar <strong>+</strong> next to Projects, or <strong>+ New project</strong>. Name: 1–50 characters.</p><ul><li>Project chats can use <strong>project files, project instructions, plugins, Skills, and Goal</strong>, and can switch models.</li><li>Each file ≤ <strong>100 MB</strong>, up to <strong>50</strong> files; read on demand, not fully preloaded every turn.</li><li>Deleting a project <strong>permanently</strong> removes its chats, files, and instructions.</li><li>Injected context: system prompt + global main memory + project instructions + on-demand files.</li><li><strong>Kimi Work Projects are not connected and do not share data.</strong></li></ul><h3 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory space</a>: preferences across chats. Official: will not memorize unauthorized private information (health, passwords, addresses) unless you ask. Manage at <strong>Settings → Personalization → Memory Space</strong>. Say &quot;Remember… / Forget… / What do you currently remember about me?&quot;. Official: not used for training; can be turned off or cleared.</p><h3 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">What are Skills?</a>: reusable knowledge packages. Type <strong><code>/</code></strong> or let Kimi trigger them. <strong><code>/skill-creator</code></strong> builds one in dialogue. Official examples: <code>docx</code>, <code>deep-research</code>; recommended: <code>sop-writer</code>, <code>event-etf-study</code>.</p><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a>: connect external tools. Available when the model is <strong>K3</strong> or <strong>K3 Swarm</strong>, and in Deep Research, Websites, and PPT. <strong>Not yet supported in Kimi Claw or Kimi Plus conversations.</strong> Entries: sidebar <strong>Plugins</strong>, input <strong>+</strong>, or <strong><code>/</code></strong>. Some need OAuth. Signed-out users cannot install. Some plugins consume membership credits on actual calls.</p><h3 id="scheduled-tasks" tabindex="-1">Scheduled tasks <a class="header-anchor" href="#scheduled-tasks" aria-label="Permalink to &quot;Scheduled tasks&quot;">​</a></h3><p><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a>: available in <strong>Kimi</strong> and <strong>Kimi Work</strong>. Sidebar &quot;Create scheduled task&quot;, or describe the schedule in chat. Cadence: daily / weekly / monthly / one-time. Cloud tasks do not need a client open. <strong>Local</strong> Kimi Work tasks require the desktop app; missed triggers while closed are not backfilled. After a run you can switch models in the result chat and type <code>/</code> for plugins and Skills.</p><p>Official template: At [time], do [task], output as [format], and follow [constraints].</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Where Goal appears officially:</p><ul><li>Membership table <strong>Goal Mode</strong>: — on Moderato; ✅ on <strong>Allegretto / Allegro / Vivace</strong> (<a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">membership overview</a>).</li><li>Project chats &quot;use plugins, Skills, and Goal&quot; (<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>).</li></ul><p>There is no standalone kimi.com Goal product page. Kimi Work has its own Goal Mode (<a href="https://www.kimi.com/help/kimi-work/overview" target="_blank" rel="noreferrer">Work overview</a>). Kimi Code <code>/goal</code> is CLI — <strong>do not</strong> type it as a kimi.com command.</p><h2 id="membership-and-credits" tabindex="-1">Membership and credits <a class="header-anchor" href="#membership-and-credits" aria-label="Permalink to &quot;Membership and credits&quot;">​</a></h2><p><a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">Membership overview</a> (opened 2026-08-19):</p><ul><li>Four tiers: <strong>Moderato $19/mo, Allegretto $39/mo, Allegro $99/mo, Vivace $199/mo</strong>.</li><li><strong>One credit pool</strong> for membership features (website deploy, Deep Research, Slides, Kimi Code, Kimi Work, Kimi Claw, K3, K3 Swarm), metered by tokens.</li><li>In Chat, <strong>K2.6 is free and does not consume credits</strong>.</li><li>Credits reset each billing cycle. Annual billing: official &quot;save up to <strong>$480/year</strong>&quot;.</li><li>Kimi Code also has a <strong>5-hour / weekly</strong> rate limit that does not affect other features.</li></ul><p>The same page&#39;s second table covers Agent concurrency, K3 extra-long chat (Allegro / Vivace, up to 1M tokens), scheduled tasks, projects, Swarm subtasks, Goal, Claw, and Claw group chats. Full numbers: <a href="./kimi-cheatsheet.html">cheatsheet</a>.</p><p><strong>Two official plan-name systems:</strong> Projects / Scheduled Tasks pages use <strong>Free / Go / Pro / Max / Ultra</strong>, and the numbers are not identical to the membership overview. This page <strong>does not invent a mapping</strong>. Prices and membership benefits: membership overview. Project / schedule caps: the feature page; if they disagree, keep both citations.</p><p>This page does <strong>not</strong> invent CNY prices. Use the membership / usage UI on your account.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Treating a generated site as a patched local git checkout. Use <a href="/products/kimi-code/">Kimi Code</a> for the repo.</li><li>Opening Swarm or one-click Claw on a plan that the membership table does not unlock (Swarm: Moderato+; one-click Claw: Allegretto+).</li><li>Assuming Kimi Work desktop projects sync with kimi.com Projects.</li><li>Typing Kimi Code <code>/goal</code> into the web box.</li><li>Merging Moderato and Go into one unofficial table.</li><li>Looking for web plugins inside Claw / Kimi Plus chats — officially unsupported.</li><li>Expecting local Kimi Work schedules to backfill while the app is closed.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use it for</th></tr></thead><tbody><tr><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td><td>The product</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a></td><td>First-class family</td></tr><tr><td><a href="https://www.kimi.com/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent overview</a></td><td>Agent entry and steps</td></tr><tr><td><a href="https://www.kimi.com/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a></td><td>Swarm entry and limits</td></tr><tr><td><a href="https://www.kimi.com/help/membership/membership-overview" target="_blank" rel="noreferrer">Membership overview</a></td><td>Plans and credit pool</td></tr><tr><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td><td>One-click / link existing OpenClaw</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">Claw group chat</a></td><td>Conductor, threads, <code>/stop</code></td></tr><tr><td><a href="https://www.kimi.com/help" target="_blank" rel="noreferrer">Help Center</a></td><td>Category index</td></tr><tr><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td><td>Company site, app download</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-cheatsheet.html">Cheatsheet</a></li><li><a href="./kimi-glossary.html">Glossary</a></li><li><a href="/products/kimi-code/">Kimi Code</a></li></ul>',67)])])}const f=t(i,[["render",s]]);export{w as __pageData,f as default};
